package model

import (
	"context"
	"fmt"
	"reflect"
	"slices"
	"time"

	"github.com/arandu-io/hesape/auth"
	"github.com/arandu-io/hesape/database/model/relations/concerns"
	"github.com/arandu-io/hesape/database/query"
	"github.com/arandu-io/hesape/str"
)

// Model is one row of a table, over the application's own struct.
//
// T is that struct, and its exported fields are the columns. The configuration
// fields below are copied onto every instance NewInstance makes.
//
// They are exported because a Go value has no subtype to override them in. Read
// the package comment before setting TenantColumn to the empty string.
type Model[T any] struct {
	// Entity is the row: a struct the compiler checks, not a dynamic map.
	//
	// It is a pointer rather than a value, and that is what lets the
	// application's own struct embed the model instead of being wrapped by it.
	// A Model[User] holding a User inside a User that holds a Model[User] is a
	// type of infinite size, and Go refuses it by name: "invalid recursive
	// type". A pointer makes the same shape finite.
	//
	// It is what a terminal hands back, and for a T that embeds Model[T] it
	// points at the value this model is inside of: the two are one allocation
	// seen from two sides. The model always has one -- NewModel and NewInstance
	// both allocate it -- so it is never nil on a model this package built.
	Entity *T

	// Table is the table name. Empty means the snake-cased plural of the type
	// name, which is what GetTable falls back to.
	Table string

	// PrimaryKey is the name of the primary key column.
	PrimaryKey string

	// KeyType is the primary key's type ("int", "string", etc.), recorded so
	// a model whose key is a uuid says so here rather than in a comment.
	KeyType string

	// Incrementing says whether the primary key is generated by the database
	// on insert.
	Incrementing bool

	// Timestamps says whether Save stamps created_at and updated_at.
	Timestamps bool

	// SoftDeletes says whether the SoftDeletingScope is registered: a
	// boolean field rather than a marker type, and NewQuery registers the
	// scope when it is set.
	SoftDeletes bool

	// TenantColumn is the column every statement is scoped by, from
	// auth.Tenant(g). It defaults to tenant_id.
	//
	// The empty string turns the scoping off, and it is spelled out at the
	// construction of the model so that a reader sees a table that is deliberately
	// global rather than a filter somebody forgot.
	//
	// It turns off the filter and nothing else. Every query method still takes
	// an auth.Grant and still refuses without one, so a table declared global is
	// a table every tenant may be allowed to read -- not a table reachable
	// without authorization. The two are separate guarantees and only this one
	// is configurable.
	TenantColumn string

	// PerPage is the default page size for Paginate.
	PerPage int

	// ConnectionName is the name of the connection this model uses.
	ConnectionName string

	// CreatedAtColumn, UpdatedAtColumn and DeletedAtColumn name the timestamp
	// columns Save and soft delete write to.
	CreatedAtColumn string
	UpdatedAtColumn string
	DeletedAtColumn string

	// embedded is where Model[T] sits inside T, plus two, so that the zero
	// value means "not resolved yet". See entityIndex.
	embedded int

	// Exists says whether the row exists in the database.
	Exists bool

	// WasRecentlyCreated says whether this model was created by the current
	// request.
	WasRecentlyCreated bool

	// connection, Grammar and Processor are given to the constructor and copied
	// onto every instance. There is no resolver to look them up in.
	//
	// The connection is unexported and nothing hands it back out. That is not
	// tidiness: query.Connection has five verbs and not one of them takes a
	// Grant, so a statement issued straight through it carries no tenant filter
	// at all. An exported field made that the shortest path out of an authorized
	// model, and an exported accessor made it a declared one -- but a declared
	// path still has to be found and refused in review, and nothing was using
	// it. What is left is no path, which the compiler enforces on its own.
	//
	// A caller that genuinely needs raw SQL still reaches the connection it
	// built the model with, or the database package. It does not get there
	// through a model that has a Grant on every other method.
	connection query.Connection
	Grammar    query.Grammar
	Processor  query.Processor

	// RelationResolvers holds one entry per relation, registered by name. Go
	// cannot look a method up by name and stay type safe, so With, Load, Has
	// and WithCount resolve relations through this map instead.
	RelationResolvers map[string]func(*Model[T]) Relation

	// NamedScopes holds one entry per scope, registered under its bare name.
	// Go cannot look a method up by name, so Scopes and CallNamedScope
	// resolve through this map instead.
	NamedScopes map[string]NamedScope[T]

	attributes map[string]any
	original   map[string]any
	changes    map[string]any
	previous   map[string]any
	relations  map[string]any

	hidden  []string
	visible []string
	appends []string

	// ref is this model seen through the interface a relation asks for, kept so
	// that two calls to Ref answer the same value.
	ref *modelRef[T]

	// touches names the relations whose owner is stamped when this model is
	// saved. It is empty by default: a save that silently stamped a parent
	// would be a write the caller did not ask for.
	touches []string

	globalScopes  map[string]Scope[T]
	events        map[Event][]func(*Model[T]) error
	muted         bool
	forceDeleting bool
}

// NewModel builds a Model over T.
//
// The three arguments after the table are handed over once, here, because there
// is no resolver to look them up in later.
//
// The defaults are id, an int key, incrementing, timestamps on, 15 per page and
// created_at / updated_at / deleted_at. TenantColumn starts at tenant_id: there
// is no default that leaves the scoping off.
func NewModel[T any](table string, connection query.Connection, grammar query.Grammar, processor query.Processor) *Model[T] {
	// Entity first, and the model from inside it when T embeds one, for the
	// reason NewInstance does the same: a model whose Entity is a second
	// allocation is a value where m.Entity.Save() and m.Save() write different
	// rows. Allocating the T and then pointing at it is what makes them one.
	entity, model := newEntity[T]()
	if model == nil {
		model = &Model[T]{}
	}
	*model = Model[T]{
		Entity:          entity,
		Table:           table,
		PrimaryKey:      "id",
		KeyType:         "int",
		Incrementing:    true,
		Timestamps:      true,
		TenantColumn:    "tenant_id",
		PerPage:         15,
		CreatedAtColumn: "created_at",
		UpdatedAtColumn: "updated_at",
		DeletedAtColumn: "deleted_at",
		connection:      connection,
		Grammar:         grammar,
		Processor:       processor,
	}
	return model
}

// Fill writes the columns the entity declares and drops the keys it does not
// know.
//
// There is no allowlist to consult beyond the struct itself: an unexported
// field is unreachable to reflection, so the allowlist is the initial letter
// of the field and the compiler keeps it (see the package comment).
//
// The error here is the other failure a typed model can have -- a value
// that does not fit the field.
func (m *Model[T]) Fill(attributes map[string]any) error {
	return m.setAttributes(attributes, false)
}

// ForceFill writes the columns the entity declares, and keeps the keys it
// does not know as raw attributes instead of dropping them the way Fill
// does. It still cannot reach an unexported field, because nothing can.
func (m *Model[T]) ForceFill(attributes map[string]any) error {
	return m.setAttributes(attributes, true)
}

// QualifyColumn returns column qualified with the model's table, unless it
// already contains a dot.
func (m *Model[T]) QualifyColumn(column string) string {
	if containsDot(column) {
		return column
	}
	return m.GetTable() + "." + column
}

// QualifyColumns returns columns, each qualified with the model's table.
func (m *Model[T]) QualifyColumns(columns []string) []string {
	out := make([]string, len(columns))
	for i, column := range columns {
		out[i] = m.QualifyColumn(column)
	}
	return out
}

// NewInstance returns a fresh model of the same shape, on the same table and
// connection, filled with the given attributes.
func (m *Model[T]) NewInstance(attributes map[string]any, exists bool) (*Model[T], error) {
	// The entity first, and the model from inside it when T embeds one: the
	// model and the entity are then one allocation, which is what lets
	// user.Save() see the fields the caller just set on user. See embed.go.
	index := m.entityIndex()
	entity := new(T)
	instance := modelIn(entity, index)
	if instance == nil {
		instance = &Model[T]{}
	}
	*instance = Model[T]{
		embedded:          m.embedded,
		Table:             m.Table,
		PrimaryKey:        m.PrimaryKey,
		KeyType:           m.KeyType,
		Incrementing:      m.Incrementing,
		Timestamps:        m.Timestamps,
		SoftDeletes:       m.SoftDeletes,
		TenantColumn:      m.TenantColumn,
		PerPage:           m.PerPage,
		ConnectionName:    m.ConnectionName,
		CreatedAtColumn:   m.CreatedAtColumn,
		UpdatedAtColumn:   m.UpdatedAtColumn,
		DeletedAtColumn:   m.DeletedAtColumn,
		connection:        m.connection,
		Grammar:           m.Grammar,
		Processor:         m.Processor,
		RelationResolvers: m.RelationResolvers,
		NamedScopes:       m.NamedScopes,
		Entity:            entity,
		Exists:            exists,
		hidden:            slices.Clone(m.hidden),
		visible:           slices.Clone(m.visible),
		appends:           slices.Clone(m.appends),
		globalScopes:      cloneScopes(m.globalScopes),
		events:            cloneEvents(m.events),
	}
	if err := instance.Fill(attributes); err != nil {
		return nil, err
	}
	return instance, nil
}

// NewFromBuilder returns the model a row becomes on the way out of the
// database, already existing and already synced.
func (m *Model[T]) NewFromBuilder(attributes map[string]any) (*Model[T], error) {
	instance, err := m.NewInstance(nil, true)
	if err != nil {
		return nil, err
	}
	if err := instance.SetRawAttributes(attributes, true); err != nil {
		return nil, err
	}
	if err := instance.fireModelEvent(Retrieved); err != nil {
		return nil, err
	}
	return instance, nil
}

// Save inserts or updates the row, and reports whether anything was written.
//
// A model that exists and is clean is a true with no statement: there is
// nothing to write.
func (m *Model[T]) Save(ctx context.Context, g auth.Grant) (bool, error) {
	// A value the framework did not build has no connection to write through,
	// and no back pointer to the entity it is inside. It is the literal case,
	// and it says so rather than reporting a write that never happened -- see
	// ErrUnwired.
	if err := m.wired(); err != nil {
		return false, err
	}

	if err := m.fireModelEvent(Saving); err != nil {
		return false, err
	}

	var (
		saved bool
		err   error
	)
	if m.Exists {
		if !m.IsDirty() {
			saved = true
		} else {
			saved, err = m.performUpdate(ctx, g)
		}
	} else {
		saved, err = m.performInsert(ctx, g)
	}
	if err != nil {
		return false, err
	}

	if saved {
		if err := m.finishSave(); err != nil {
			return false, err
		}
	}
	return saved, nil
}

// SaveQuietly saves the model without firing model events.
func (m *Model[T]) SaveQuietly(ctx context.Context, g auth.Grant) (saved bool, err error) {
	return saved, m.WithoutEvents(func() error {
		saved, err = m.Save(ctx, g)
		return err
	})
}

// SaveOrFail is the save, inside a transaction.
//
// query.Connection has no transaction on it, so the connection is asked whether
// it can open one, and a connection that cannot says so instead of writing
// outside a transaction the caller believes it is in.
func (m *Model[T]) SaveOrFail(ctx context.Context, g auth.Grant) (bool, error) {
	var saved bool
	err := m.transaction(func() error {
		var err error
		saved, err = m.Save(ctx, g)
		return err
	})
	return saved, err
}

// Update fills the model with attributes, then saves it. A model that does
// not exist yet is false and no statement.
func (m *Model[T]) Update(ctx context.Context, g auth.Grant, attributes map[string]any) (bool, error) {
	// A value the framework did not build has no connection to write through,
	// and no back pointer to the entity it is inside. It is the literal case,
	// and it says so rather than reporting a write that never happened -- see
	// ErrUnwired.
	if err := m.wired(); err != nil {
		return false, err
	}

	if !m.Exists {
		return false, nil
	}
	if err := m.Fill(attributes); err != nil {
		return false, err
	}
	return m.Save(ctx, g)
}

// UpdateQuietly updates the model without firing model events.
func (m *Model[T]) UpdateQuietly(ctx context.Context, g auth.Grant, attributes map[string]any) (saved bool, err error) {
	return saved, m.WithoutEvents(func() error {
		saved, err = m.Update(ctx, g, attributes)
		return err
	})
}

// UpdateOrFail is Update, inside a transaction.
func (m *Model[T]) UpdateOrFail(ctx context.Context, g auth.Grant, attributes map[string]any) (bool, error) {
	if !m.Exists {
		return false, nil
	}
	if err := m.Fill(attributes); err != nil {
		return false, err
	}
	return m.SaveOrFail(ctx, g)
}

// Push saves the model and everything loaded on it.
//
// A loaded relation is held as an any, so Push recurses into whatever
// implements Pushable -- *Model[R] and Collection[R] both do.
func (m *Model[T]) Push(ctx context.Context, g auth.Grant) (bool, error) {
	// A value the framework did not build has no connection to write through,
	// and no back pointer to the entity it is inside. It is the literal case,
	// and it says so rather than reporting a write that never happened -- see
	// ErrUnwired.
	if err := m.wired(); err != nil {
		return false, err
	}

	saved, err := m.Save(ctx, g)
	if err != nil || !saved {
		return saved, err
	}
	for _, related := range m.relations {
		pushable, ok := related.(Pushable)
		if !ok {
			continue
		}
		pushed, err := pushable.Push(ctx, g)
		if err != nil || !pushed {
			return false, err
		}
	}
	return true, nil
}

// PushQuietly pushes the model without firing model events.
func (m *Model[T]) PushQuietly(ctx context.Context, g auth.Grant) (pushed bool, err error) {
	return pushed, m.WithoutEvents(func() error {
		pushed, err = m.Push(ctx, g)
		return err
	})
}

// Pushable is what Push recurses into. See Push.
type Pushable interface {
	Push(ctx context.Context, g auth.Grant) (bool, error)
}

// finishSave fires the Saved event and syncs the original snapshot.
//
// It does not touch the owners of loaded relations: doing that needs the
// relation to say who its owner is, which lives in model/relations.
func (m *Model[T]) finishSave() error {
	if err := m.fireModelEvent(Saved); err != nil {
		return err
	}
	m.SyncOriginal()
	return nil
}

// performUpdate fires the Updating/Updated events and writes the dirty
// columns for a model that already exists.
func (m *Model[T]) performUpdate(ctx context.Context, g auth.Grant) (bool, error) {
	if err := m.fireModelEvent(Updating); err != nil {
		return false, err
	}
	if m.UsesTimestamps() {
		m.UpdateTimestamps()
	}

	dirty := m.GetDirty()
	if len(dirty) == 0 {
		return true, nil
	}

	q := m.NewModelQuery()
	m.setKeysForSaveQuery(q)
	if _, err := q.Update(ctx, g, dirty); err != nil {
		return false, err
	}

	m.SyncChanges()
	if err := m.fireModelEvent(Updated); err != nil {
		return false, err
	}
	return true, nil
}

// performInsert fires the Creating/Created events and inserts the row for a
// model that does not exist yet.
func (m *Model[T]) performInsert(ctx context.Context, g auth.Grant) (bool, error) {
	if err := m.fireModelEvent(Creating); err != nil {
		return false, err
	}
	if m.UsesTimestamps() {
		m.UpdateTimestamps()
	}

	attributes := m.getAttributesForInsert()
	q := m.NewModelQuery()

	if m.Incrementing {
		id, err := q.InsertGetID(ctx, g, attributes, m.GetKeyName())
		if err != nil {
			return false, err
		}
		if err := m.SetAttribute(m.GetKeyName(), id); err != nil {
			return false, err
		}
	} else {
		if len(attributes) == 0 {
			return true, nil
		}
		if _, err := q.Insert(ctx, g, attributes); err != nil {
			return false, err
		}
	}

	m.Exists = true
	m.WasRecentlyCreated = true

	if err := m.fireModelEvent(Created); err != nil {
		return false, err
	}
	return true, nil
}

// getAttributesForInsert returns the row's columns for an insert statement.
//
// It drops the key of an incrementing model when the key is still zero. A Go
// struct always carries the field, so a zero key cannot simply be absent the
// way an unset property would be; inserting id = 0 into an auto-increment
// column is a row with the wrong id on MySQL and an error on Postgres.
func (m *Model[T]) getAttributesForInsert() map[string]any {
	attributes := m.GetAttributes()
	if m.Incrementing {
		if value, ok := attributes[m.GetKeyName()]; ok && isZero(value) {
			delete(attributes, m.GetKeyName())
		}
	}
	return attributes
}

// setKeysForSaveQuery adds the primary key filter a save statement runs
// under.
func (m *Model[T]) setKeysForSaveQuery(b *Builder[T]) *Builder[T] {
	return b.Where(m.GetQualifiedKeyName(), "=", m.getKeyForSaveQuery())
}

// getKeyForSaveQuery returns the original key, so that changing the key of a
// loaded row updates the right one.
func (m *Model[T]) getKeyForSaveQuery() any {
	if original, ok := m.original[m.GetKeyName()]; ok {
		return original
	}
	return m.GetKey()
}

// Delete removes the row, and reports whether it was deleted.
//
// A model that does not exist returns false with no error: a Go bool has no
// third state, and "there was nothing to delete" is not a failure.
func (m *Model[T]) Delete(ctx context.Context, g auth.Grant) (bool, error) {
	// A value the framework did not build has no connection to write through,
	// and no back pointer to the entity it is inside. It is the literal case,
	// and it says so rather than reporting a write that never happened -- see
	// ErrUnwired.
	if err := m.wired(); err != nil {
		return false, err
	}

	if m.GetKeyName() == "" {
		return false, ErrNoKey
	}
	if !m.Exists {
		return false, nil
	}
	if err := m.fireModelEvent(Deleting); err != nil {
		return false, err
	}
	if err := m.performDeleteOnModel(ctx, g); err != nil {
		return false, err
	}
	if err := m.fireModelEvent(Deleted); err != nil {
		return false, err
	}
	return true, nil
}

// DeleteQuietly deletes the model without firing model events.
func (m *Model[T]) DeleteQuietly(ctx context.Context, g auth.Grant) (deleted bool, err error) {
	return deleted, m.WithoutEvents(func() error {
		deleted, err = m.Delete(ctx, g)
		return err
	})
}

// DeleteOrFail is Delete, inside a transaction.
func (m *Model[T]) DeleteOrFail(ctx context.Context, g auth.Grant) (bool, error) {
	if !m.Exists {
		return false, nil
	}
	var deleted bool
	err := m.transaction(func() error {
		var err error
		deleted, err = m.Delete(ctx, g)
		return err
	})
	return deleted, err
}

// Destroy deletes the rows with the given primary keys, and returns how many
// were deleted.
//
// It loads the rows and deletes them one at a time, so that a soft delete
// stays a soft delete and every event fires with the row it is about.
func (m *Model[T]) Destroy(ctx context.Context, g auth.Grant, ids ...any) (int, error) {
	if len(ids) == 0 {
		return 0, nil
	}
	found, err := m.NewQuery().WhereKey(ids).get(ctx, g)
	if err != nil {
		return 0, err
	}
	count := 0
	for _, model := range found {
		deleted, err := model.Delete(ctx, g)
		if err != nil {
			return count, err
		}
		if deleted {
			count++
		}
	}
	return count, nil
}

// Fresh returns the same row, read again, as a new model.
//
// It queries without the global scopes, which is what makes it able to find a
// row that has since been soft deleted.
func (m *Model[T]) Fresh(ctx context.Context, g auth.Grant, with ...string) (*T, error) {
	if !m.Exists {
		return nil, nil
	}
	q := m.NewQueryWithoutScopes().With(with...)
	m.setKeysForSelectQuery(q)
	return q.First(ctx, g)
}

// Refresh reads the same row again, into this model.
func (m *Model[T]) Refresh(ctx context.Context, g auth.Grant) error {
	// A value the framework did not build has no connection to write through,
	// and no back pointer to the entity it is inside. It is the literal case,
	// and it says so rather than reporting a write that never happened -- see
	// ErrUnwired.
	if err := m.wired(); err != nil {
		return err
	}

	if !m.Exists {
		return nil
	}
	q := m.NewQueryWithoutScopes()
	m.setKeysForSelectQuery(q)
	fresh, err := q.firstOrFail(ctx, g)
	if err != nil {
		return err
	}
	if err := m.SetRawAttributes(fresh.GetAttributes(), true); err != nil {
		return err
	}
	loaded := make([]string, 0, len(m.relations))
	for name := range m.relations {
		loaded = append(loaded, name)
	}
	slices.Sort(loaded)
	return m.Load(ctx, g, loaded...)
}

// setKeysForSelectQuery adds the primary key filter a select statement runs
// under.
func (m *Model[T]) setKeysForSelectQuery(b *Builder[T]) *Builder[T] {
	return b.Where(m.GetQualifiedKeyName(), "=", m.getKeyForSaveQuery())
}

// Replicate returns the same row as a new, unsaved model.
//
// The key, the timestamps and anything named in except are left out.
func (m *Model[T]) Replicate(except ...string) (*T, error) {
	instance, err := m.replicate(except...)
	if err != nil {
		return nil, err
	}
	return instance.Entity, nil
}

// replicate is Replicate with the model still in hand. See Builder.get.
func (m *Model[T]) replicate(except ...string) (*Model[T], error) {
	defaults := []string{m.GetKeyName(), m.GetCreatedAtColumn(), m.GetUpdatedAtColumn()}
	drop := append(slices.Clone(except), defaults...)

	attributes := m.GetAttributes()
	for _, key := range drop {
		if key != "" {
			delete(attributes, key)
		}
	}

	instance, err := m.NewInstance(nil, false)
	if err != nil {
		return nil, err
	}
	if err := instance.SetRawAttributes(attributes, false); err != nil {
		return nil, err
	}
	instance.relations = copyMap(m.relations)
	if err := instance.fireModelEvent(Replicating); err != nil {
		return nil, err
	}
	return instance, nil
}

// ReplicateQuietly replicates the model without firing model events.
func (m *Model[T]) ReplicateQuietly(except ...string) (copied *T, err error) {
	return copied, m.WithoutEvents(func() error {
		copied, err = m.Replicate(except...)
		return err
	})
}

// Is reports whether other is the same row: the same key, on the same table, on
// the same connection.
//
// It takes the row, which is what a terminal hands back, and what it can answer
// depends on the shape of T. A T that embeds Model[T] carries its model inside
// itself, so a.Is(b) on two rows reaches the key and the table on both. A T that
// does not has no field pointing back at a model, and this answers false: a
// table and a connection are not columns, so a plain row does not carry them.
func (m *Model[T]) Is(other *T) bool { return m.is(ModelOf(other)) }

// IsNot reports the opposite of Is.
func (m *Model[T]) IsNot(other *T) bool { return !m.Is(other) }

// is is Is with the model still in hand, which is what the package holds when it
// compares rows to each other.
func (m *Model[T]) is(other *Model[T]) bool {
	return other != nil &&
		reflect.DeepEqual(m.GetKey(), other.GetKey()) &&
		m.GetTable() == other.GetTable() &&
		m.GetConnectionName() == other.GetConnectionName()
}

// Load eager loads these relations onto this model.
func (m *Model[T]) Load(ctx context.Context, g auth.Grant, relations ...string) error {
	if len(relations) == 0 {
		return nil
	}
	return m.NewQueryWithoutRelationships().With(relations...).eagerLoadRelations(ctx, g, models[T]{m})
}

// LoadMissing eager loads these relations onto this model, skipping the ones
// already loaded.
func (m *Model[T]) LoadMissing(ctx context.Context, g auth.Grant, relations ...string) error {
	return models[T]{m}.LoadMissing(ctx, g, relations...)
}

// LoadCount loads the count of each relation onto this model.
func (m *Model[T]) LoadCount(ctx context.Context, g auth.Grant, relations ...string) error {
	return models[T]{m}.LoadCount(ctx, g, relations...)
}

// LoadAggregate loads function over column of each relation onto this model.
func (m *Model[T]) LoadAggregate(ctx context.Context, g auth.Grant, relations []string, column, function string) error {
	return models[T]{m}.LoadAggregate(ctx, g, relations, column, function)
}

// GetRelation returns the value loaded for a relation, and whether it was
// loaded at all.
//
// The value is an any because the related rows are models of another type,
// and a Go field cannot hold "some other model". Related is the typed way to
// read it.
//
// A name the model declares a relation for, asked for before anything
// loaded it, is the lazy load this framework does not do: it reports false
// rather than running a query, and PreventLazyLoading is what makes that
// silence loud.
func (m *Model[T]) GetRelation(name string) (any, bool) {
	value, ok := m.relations[name]
	if !ok {
		if _, declared := m.RelationResolvers[name]; declared {
			m.handleLazyLoadingViolation(name)
		}
	}
	return value, ok
}

// SetRelation records value as the loaded relation named name.
func (m *Model[T]) SetRelation(name string, value any) *Model[T] {
	if m.relations == nil {
		m.relations = map[string]any{}
	}
	m.relations[name] = value
	return m
}

// RelationLoaded reports whether name has a loaded value.
func (m *Model[T]) RelationLoaded(name string) bool {
	_, ok := m.relations[name]
	return ok
}

// GetRelations returns every loaded relation.
func (m *Model[T]) GetRelations() map[string]any { return copyMap(m.relations) }

// SetRelations replaces every loaded relation.
func (m *Model[T]) SetRelations(relations map[string]any) *Model[T] {
	m.relations = copyMap(relations)
	return m
}

// UnsetRelation removes the loaded relation named name.
func (m *Model[T]) UnsetRelation(name string) *Model[T] {
	delete(m.relations, name)
	return m
}

// UnsetRelations removes every loaded relation.
func (m *Model[T]) UnsetRelations() *Model[T] {
	m.relations = nil
	return m
}

// WithoutRelations returns the same row, with nothing loaded hanging off it.
func (m *Model[T]) WithoutRelations() (*T, error) {
	instance, err := m.NewInstance(nil, m.Exists)
	if err != nil {
		return nil, err
	}
	if err := instance.SetRawAttributes(m.GetAttributes(), false); err != nil {
		return nil, err
	}
	instance.original = copyMap(m.original)
	return instance.Entity, nil
}

// Related reads a loaded relation off the row, as the type it was loaded as.
//
// The relation was loaded as rows of another type, which Go cannot spell as a
// field, so the read is a generic function rather than a method:
//
//	posts, ok := model.Related[User, Post](user, "posts")
//
// It reports false when the relation was not loaded, when it was loaded as
// something else, and when the row carries no model to read it off.
//
// That last one is the shape of T. A T that embeds Model[T] carries its model
// inside itself, so the relation an eager load attached is on the row this takes.
// A T that does not has no field pointing back: the relation is on a model
// beside the row, which no terminal hands back, so there is nothing here to read
// and the answer is false rather than a dereference of nothing.
func Related[T, R any](row *T, name string) (Collection[R], bool) {
	m := ModelOf(row)
	if m == nil {
		return nil, false
	}
	value, ok := m.GetRelation(name)
	if !ok {
		return nil, false
	}
	switch typed := value.(type) {
	case Collection[R]:
		return typed, true
	case *Model[R]:
		return Collection[R]{typed.Entity}, true

	// What a relation loads is erased -- the relations tree holds the narrow
	// interface, not the typed model -- so the way back is through the adapter.
	// A ref over another entity reads as not loaded rather than as a panic.
	case []concerns.Model:
		out := make(Collection[R], 0, len(typed))
		for _, one := range typed {
			model, ok := Unref[R](one)
			if !ok {
				return nil, false
			}
			out = append(out, model.Entity)
		}
		return out, true
	case concerns.Model:
		model, ok := Unref[R](typed)
		if !ok {
			return nil, false
		}
		return Collection[R]{model.Entity}, true
	}
	return nil, false
}

// GetKey returns the value of the primary key column.
func (m *Model[T]) GetKey() any { return m.GetAttribute(m.GetKeyName()) }

// GetKeyName returns the name of the primary key column.
func (m *Model[T]) GetKeyName() string { return m.PrimaryKey }

// SetKeyName replaces the name of the primary key column.
func (m *Model[T]) SetKeyName(key string) *Model[T] {
	m.PrimaryKey = key
	return m
}

// GetQualifiedKeyName returns the primary key column qualified with the
// model's table.
func (m *Model[T]) GetQualifiedKeyName() string { return m.QualifyColumn(m.GetKeyName()) }

// GetKeyType returns the primary key's type.
func (m *Model[T]) GetKeyType() string { return m.KeyType }

// SetKeyType replaces the primary key's type.
func (m *Model[T]) SetKeyType(keyType string) *Model[T] {
	m.KeyType = keyType
	return m
}

// GetIncrementing reports whether the primary key is generated by the
// database on insert.
func (m *Model[T]) GetIncrementing() bool { return m.Incrementing }

// SetIncrementing replaces whether the primary key is generated by the
// database on insert.
func (m *Model[T]) SetIncrementing(value bool) *Model[T] {
	m.Incrementing = value
	return m
}

// GetTable returns the table name: Table when it is set, or else the name
// of T, pluralised and snake cased, so a struct called User reads from
// users.
func (m *Model[T]) GetTable() string {
	if m.Table != "" {
		return m.Table
	}
	name := reflect.TypeFor[T]().Name()
	if name == "" {
		return ""
	}
	return str.Snake(str.PluralStudly(name), "_")
}

// SetTable replaces the table name.
func (m *Model[T]) SetTable(table string) *Model[T] {
	m.Table = table
	return m
}

// GetConnectionName returns the name of the connection this model uses.
func (m *Model[T]) GetConnectionName() string { return m.ConnectionName }

// SetConnection replaces the connection name and, when connection is not
// nil, the connection itself.
//
// It takes the connection as well as the name because there is no resolver to
// look one up in: a name on its own reaches nothing.
func (m *Model[T]) SetConnection(name string, connection query.Connection) *Model[T] {
	m.ConnectionName = name
	if connection != nil {
		m.connection = connection
	}
	return m
}

// GetPerPage returns the default page size for Paginate, or 15 when PerPage
// is not set to a positive value.
func (m *Model[T]) GetPerPage() int {
	if m.PerPage <= 0 {
		return 15
	}
	return m.PerPage
}

// SetPerPage replaces the default page size for Paginate.
func (m *Model[T]) SetPerPage(perPage int) *Model[T] {
	m.PerPage = perPage
	return m
}

// GetForeignKey returns the name this model has when another table points
// at it.
func (m *Model[T]) GetForeignKey() string {
	name := reflect.TypeFor[T]().Name()
	return str.Snake(name, "_") + "_" + m.GetKeyName()
}

// UsesTimestamps reports whether Save stamps created_at and updated_at.
func (m *Model[T]) UsesTimestamps() bool { return m.Timestamps }

// GetCreatedAtColumn returns the name of the created-at column.
func (m *Model[T]) GetCreatedAtColumn() string { return m.CreatedAtColumn }

// GetUpdatedAtColumn returns the name of the updated-at column.
func (m *Model[T]) GetUpdatedAtColumn() string { return m.UpdatedAtColumn }

// GetQualifiedCreatedAtColumn returns the created-at column qualified with
// the model's table.
func (m *Model[T]) GetQualifiedCreatedAtColumn() string {
	return m.QualifyColumn(m.GetCreatedAtColumn())
}

// GetQualifiedUpdatedAtColumn returns the updated-at column qualified with
// the model's table.
func (m *Model[T]) GetQualifiedUpdatedAtColumn() string {
	return m.QualifyColumn(m.GetUpdatedAtColumn())
}

// FreshTimestamp returns the current time in UTC.
func (m *Model[T]) FreshTimestamp() time.Time { return time.Now().UTC() }

// WithoutTimestamps runs callback with the timestamps switched off, and
// restores the previous setting however it ends.
func (m *Model[T]) WithoutTimestamps(callback func() error) error {
	previous := m.Timestamps
	m.Timestamps = false
	defer func() { m.Timestamps = previous }()
	return callback()
}

// UpdateTimestamps stamps the updated-at column, and the created-at column
// when the model does not yet exist.
//
// A column the entity does not declare is skipped rather than written as a
// raw attribute: a model without a created_at field is a table without the
// column, and inserting one would fail on the first row.
func (m *Model[T]) UpdateTimestamps() {
	now := m.FreshTimestamp()
	if column := m.GetUpdatedAtColumn(); m.hasColumn(column) {
		_, _ = m.setAttribute(column, now)
	}
	if column := m.GetCreatedAtColumn(); !m.Exists && m.hasColumn(column) {
		_, _ = m.setAttribute(column, now)
	}
}

// hasColumn reports whether the entity declares this column.
func (m *Model[T]) hasColumn(column string) bool {
	if column == "" {
		return false
	}
	_, ok := fieldByColumn(reflect.TypeFor[T](), column)
	return ok
}

// transaction runs fn inside a transaction when the connection can open one.
//
// See SaveOrFail for why it is an assertion rather than a method on
// query.Connection.
func (m *Model[T]) transaction(fn func() error) error {
	transactor, ok := m.connection.(Transactor)
	if !ok {
		return fmt.Errorf("model: %s: the connection cannot open a transaction, so this cannot be the atomic form", m.GetTable())
	}
	return transactor.Transaction(fn)
}

// Transactor is a connection that can open a transaction.
//
// The narrow query.Connection this component builds on does not declare one, and
// widening it would change a contract this package does not own. So the
// capability is asked for by assertion, which is how Go spells an optional one.
type Transactor interface {
	// Transaction runs callback inside a database transaction.
	Transaction(callback func() error) error
}

// Savepointer is a Transactor that also reports how deep it already is.
//
// It is what Builder.WithSavepointIfNeeded asks for, and it is separate from
// Transactor because a connection can be able to open a transaction without
// being able to say whether one is open -- and guessing wrong there is either a
// savepoint nobody asked for or a rollback that takes the caller's work with it.
type Savepointer interface {
	Transactor

	// TransactionLevel returns how many transactions are currently nested.
	TransactionLevel() int
}

func containsDot(s string) bool {
	for i := range len(s) {
		if s[i] == '.' {
			return true
		}
	}
	return false
}
